package com.acme.proto;

/**
 * Hand-written stand-in. src/generated/java/com/acme/proto/Ticket.java
 * declares the same fully qualified name from a second source root, so
 * "com.acme.proto.Ticket" has two candidate files and no way to choose.
 */
public final class Ticket {
    public final String id;

    public Ticket(String id) {
        this.id = id;
    }
}
